    private boolean canChangePages(){return !busy&&!loadingPage&&!markupState.active&&pages.size()>1;}
    private void updatePageNavigation(){
        if(previousPage!=null){previousPage.setEnabled(canChangePages()&&index>0);previousPage.setAlpha(previousPage.isEnabled()?1f:.35f);}
        if(nextPage!=null){nextPage.setEnabled(canChangePages()&&index+1<pages.size());nextPage.setAlpha(nextPage.isEnabled()?1f:.35f);}
    }
    private void showEditorPage(int target){
        if(!canChangePages()||target<0||target>=pages.size()||target==index)return;
        String origin=getIntent().getStringExtra("edit_source");if(origin==null)origin=appendPath;
        if(origin!=null&&!FolderLock.ensureDocument(this,origin,()->showEditorPage(target)))return;
        index=target;render();
    }
    private void enablePageSwipes(PagePreview image){
        final int slop=ViewConfiguration.get(this).getScaledTouchSlop();
        image.setOnTouchListener(new View.OnTouchListener(){
            float startX,startY;boolean tracking;
            @Override public boolean onTouch(View view,MotionEvent event){
                switch(event.getActionMasked()){
                    case MotionEvent.ACTION_DOWN:
                        tracking=canChangePages();startX=event.getX();startY=event.getY();return tracking;
                    case MotionEvent.ACTION_POINTER_DOWN:
                    case MotionEvent.ACTION_CANCEL:
                        tracking=false;return true;
                    case MotionEvent.ACTION_MOVE:
                        if(event.getPointerCount()!=1){tracking=false;return true;}
                        if(Math.abs(event.getY()-startY)>slop&&Math.abs(event.getY()-startY)>Math.abs(event.getX()-startX))tracking=false;
                        return true;
                    case MotionEvent.ACTION_UP:
                        boolean swipe=tracking&&event.getPointerCount()==1&&canChangePages();tracking=false;
                        float dx=event.getX()-startX,dy=event.getY()-startY;
                        if(swipe&&Math.abs(dx)>=Math.max(dp(48),view.getWidth()*.12f)&&Math.abs(dx)>Math.abs(dy)*1.5f)showEditorPage(index+(dx<0?1:-1));
                        else if(swipe&&Math.hypot(dx,dy)<=slop)view.performClick();
                        return true;
                    default:return tracking;
                }
            }
        });
    }
    private void action(LinearLayout row,String title,String symbol,Runnable run){TextView t=text(title,11,cropStage?Color.WHITE:INK);t.setGravity(Gravity.CENTER);AppIcon d=new AppIcon(symbol,cropStage?Color.WHITE:INK);d.setBounds(0,0,dp(25),dp(25));t.setCompoundDrawables(null,d,null,null);t.setCompoundDrawablePadding(dp(3));row.addView(t,new LinearLayout.LayoutParams(0,-1,1));pageActions.add(t);t.setOnClickListener(v->{if(!busy&&!loadingPage)run.run();});}
    private void editorOptions(View anchor){PopupMenu menu=new PopupMenu(this,anchor);for(String label:new String[]{"Crop","Pages","Add pages","Delete page","Apply filter to all pages","Apply filter to selected pages","Brightness / contrast","Retake this page","Rename","OCR Languages"})UiText.add(menu.getMenu(), label);menu.setOnMenuItemClickListener(item->{if(busy)return true;switch(UiText.canonical(item)){case "Apply filter to all pages":new AlertDialog.Builder(this).setTitle(UiText.get(R.string.ui_filter_for_all_pages)).setSingleChoiceItems(UiText.labels(filterNames),filters.get(index),(d,w)->{int light=brightness.get(index),tone=contrast.get(index);Collections.fill(filters,w);Collections.fill(brightness,light);Collections.fill(contrast,tone);d.dismiss();render();}).show();break;case "Apply filter to selected pages":chooseFilterPages();break;case "Brightness / contrast":toneOptions();break;case "Retake this page":retakeIndex=index;camera.launch(new Intent(this,CameraCaptureActivity.class).putExtra("capture_mode","Single"));break;case "Crop":cropStage=true;render();break;case "Pages":pageOptions();break;case "Add pages":retakeIndex=-1;camera.launch(new Intent(this,CameraCaptureActivity.class).putExtra("capture_mode","Batch"));break;case "Delete page":deletePage();break;case "Rename":rename();break;case "OCR Languages":startActivity(new Intent(this,LanguageManagerActivity.class).putExtra("kind","ocr"));break;}return true;});menu.show();}
