    private static void drawInk(Canvas canvas,ArrayList<InkStroke> strokes,RectF rect){Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setStyle(Paint.Style.STROKE);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);for(InkStroke stroke:strokes){if(stroke.points.size()<2)continue;Path path=new Path();float x=rect.left+stroke.points.get(0)*rect.width(),y=rect.top+stroke.points.get(1)*rect.height();path.moveTo(x,y);path.lineTo(x+.1f,y+.1f);for(int i=2;i+1<stroke.points.size();i+=2)path.lineTo(rect.left+stroke.points.get(i)*rect.width(),rect.top+stroke.points.get(i+1)*rect.height());paint.setColor(stroke.color);paint.setStrokeWidth(Math.max(1,stroke.width*rect.width()/1000f));canvas.drawPath(path,paint);}}
