        RectF imageRect(){Bitmap bitmap=markupState.bitmap;if(bitmap==null)return new RectF();float scale=Math.min((getWidth()-dp(24))/(float)bitmap.getWidth(),(getHeight()-dp(24))/(float)bitmap.getHeight());float w=bitmap.getWidth()*scale,h=bitmap.getHeight()*scale;return new RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);}
        @Override protected void onDraw(Canvas canvas){Bitmap bitmap=markupState.bitmap;if(bitmap==null||bitmap.isRecycled())return;RectF rect=imageRect();canvas.drawBitmap(bitmap,null,rect,paint);int save=canvas.save();canvas.clipRect(rect);drawInk(canvas,markupState.strokes,rect);canvas.restoreToCount(save);}
