    private Bitmap perspective(Bitmap source,float[] p){return PageGeometry.crop(source,p);}
    private Bitmap applyFilter(Bitmap source,int selected,int page){
        if(selected==0)return source.copy(Bitmap.Config.ARGB_8888,false);
        String key=pages.get(page)+"#"+rotations.get(page)+"#"+Arrays.toString(crops.get(page));
        Integer color=scanModes.get(key);if(color==null){color=ScanEngine.colorMode(source);scanModes.put(key,color);}
        Bitmap prepared=source;try{int curved=pageConfigs.get(page).optInt("dewarp",1);if(curved==2||curved==1&&"Book".equals(pageMode(page)))prepared=CurvedPaper.flatten(this,source,key);Bitmap clean=ScanCleanup.apply(prepared,pageConfigs.get(page).optBoolean("fingers"),pageConfigs.get(page).optBoolean("demoire"));try{return ScanEngine.enhance(clean,color);}finally{if(clean!=prepared)clean.recycle();}}catch(Exception e){throw new IllegalStateException(UiText.get(R.string.ui_could_not_flatten_this_page_turn_off_curved_paper_in_scan_preferences_to_ke),e);}finally{if(prepared!=source)prepared.recycle();}
    }
    private Bitmap filter(Bitmap source,int selected){Bitmap result=applyFilter(source,selected,index);source.recycle();return result;}
