    private boolean validCrop(float[] p){float area=0;for(int i=0;i<4;i++){int j=(i+1)%4,k=(i+2)%4;float cross=(p[j*2]-p[i*2])*(p[k*2+1]-p[j*2+1])-(p[j*2+1]-p[i*2+1])*(p[k*2]-p[j*2]);if(cross<=.0001f)return false;area+=p[i*2]*p[j*2+1]-p[j*2]*p[i*2+1];}return area>.02f;}
